--- backend/src/InvoiceApp.Domain/ApprovalService.cs ---
   1: namespace InvoiceApp.Domain;
   2: 
   3: /// <summary>
   4: /// Moves an invoice through its lifecycle: Draft -> PendingApproval -> Approved or Rejected.
   5: /// One invoice at a time, decided as a whole by a single approver.
   6: /// </summary>
   7: public class ApprovalService
   8: {
   9:     private readonly IInvoiceRepository _repository;
  10: 
  11:     public ApprovalService(IInvoiceRepository repository)
  12:     {
  13:         _repository = repository;
  14:     }
  15: 
  16:     public Invoice Submit(string invoiceId)
  17:     {
  18:         var invoice = Find(invoiceId);
  19: 
  20:         if (invoice.Status != InvoiceStatus.Draft)
  21:         {
  22:             throw new InvalidOperationException(
  23:                 $"Invoice {invoiceId} is {invoice.Status}; only drafts can be submitted.");
  24:         }
  25: 
  26:         invoice.Status = InvoiceStatus.PendingApproval;
  27:         _repository.Update(invoice);
  28:         return invoice;
  29:     }
  30: 
  31:     public Invoice Approve(string invoiceId, string approver, string role)
  32:     {
  33:         var invoice = Find(invoiceId);
  34:         EnsurePending(invoice);
  35:         EnsureApprovalAllowed(invoice, role);
  36: 
  37:         invoice.Status = InvoiceStatus.Approved;
  38:         invoice.DecidedBy = approver;
  39:         invoice.DecidedAt = DateTime.UtcNow;
  40:         _repository.Update(invoice);
  41:         return invoice;
  42:     }
  43: 
  44:     public Invoice Reject(string invoiceId, string approver, string reason)
  45:     {
  46:         if (string.IsNullOrWhiteSpace(reason))
  47:         {
  48:             throw new ArgumentException("A reason is required to reject an invoice.", nameof(reason));
  49:         }
  50: 
  51:         var invoice = Find(invoiceId);
  52:         EnsurePending(invoice);
  53: 
  54:         invoice.Status = InvoiceStatus.Rejected;
  55:         invoice.DecidedBy = approver;
  56:         invoice.DecidedAt = DateTime.UtcNow;
  57:         invoice.DecisionNote = reason;
  58:         _repository.Update(invoice);
  59:         return invoice;
  60:     }
  61: 
  62:     private Invoice Find(string invoiceId) =>
  63:         _repository.GetById(invoiceId)
  64:         ?? throw new KeyNotFoundException($"Invoice {invoiceId} was not found.");
  65: 
  66:     private static void EnsurePending(Invoice invoice)
  67:     {
  68:         if (invoice.Status != InvoiceStatus.PendingApproval)
  69:         {
  70:             throw new InvalidOperationException(
  71:                 $"Invoice {invoice.Id} is {invoice.Status}; only pending invoices can be decided.");
  72:         }
  73:     }
  74: 
  75:     private static void EnsureApprovalAllowed(Invoice invoice, string role)
  76:     {
  77:         if (role == "Manager" && invoice.Amount <= 50_000m)
  78:         {
  79:             return;
  80:         }
  81: 
  82:         if (role == "Director" && invoice.Amount <= 500_000m)
  83:         {
  84:             return;
  85:         }
  86: 
  87:         var reason = role switch
  88:         {
  89:             "Manager" => "Managers may approve invoices only up to 50000.",
  90:             "Director" => "Directors may approve invoices only up to 500000 in a single approval.",
  91:             _ => $"Role '{role}' is not authorized to approve invoices.",
  92:         };
  93: 
  94:         throw new InvalidOperationException(reason);
  95:     }
  96: }

