    [Fact]
    public void Approve_ManagerAtDirectorLimit_FailsWithoutMutation()
    {
        var invoice = InvoiceWith("INV-1", InvoiceStatus.PendingApproval);
        invoice.Amount = 500_000m;
        var originalState = SnapshotInvoice(invoice);
