        Assert.Equal(InvoiceStatus.Approved, finalApproval.Status);
        Assert.Equal(2, finalApproval.ApprovalHistory.Count);

        Invoice? TryApprove(string approver)
        {
            try
            {
                return service.Approve("INV-1", approver, "Manager");
