        var stateAfterFirstApproval = SnapshotInvoice(host.GetInvoice());
        host.SetSession("Manager", "second.manager");
        var invalidSecondResponse = await host.Client.PostAsJsonAsync(
            $"/api/approvals/{host.Invoice.Id}/approve",
