    [Fact]
    public async Task Approve_ManagerOverLimit_ReturnsConflictAndClearReasonWithoutMutation()
    {
        using var host = new ApiTestHost("Manager", "manager.user", amount: 50_001m);

        var response = await host.Client.PostAsync(
            $"/api/approvals/{host.Invoice.Id}/approve",
            content: null);

        Assert.Equal(HttpStatusCode.Conflict, response.StatusCode);
        var body = await response.Content.ReadFromJsonAsync<JsonElement>();
        Assert.Equal(
            "Managers may approve invoices only up to 50000.",
            body.GetProperty("error").GetString());
        AssertInvoiceUnchanged(host);
    }

    [Fact]
    public async Task Approve_HighValueFlow_UsesAuthenticatedSessionForBothApprovals()
    {
        using var host = new ApiTestHost("Manager", "manager.user", amount: 600_001m);

        var firstResponse = await host.Client.PostAsJsonAsync(
            $"/api/approvals/{host.Invoice.Id}/approve",
            new { username = "forged.director", role = "Director" });

        Assert.Equal(HttpStatusCode.OK, firstResponse.StatusCode);
        var provisionalInvoice = await firstResponse.Content.ReadFromJsonAsync<Invoice>();
        Assert.NotNull(provisionalInvoice);
        Assert.Equal(InvoiceStatus.PendingApproval, provisionalInvoice.Status);
        Assert.Null(provisionalInvoice.DecidedBy);
        Assert.Null(provisionalInvoice.DecidedAt);
        var firstApproval = Assert.Single(provisionalInvoice.ApprovalHistory);
        Assert.Equal("manager.user", firstApproval.Approver);
        Assert.Equal("Manager", firstApproval.Role);

        var stateAfterFirstApproval = SnapshotInvoice(host.GetInvoice());
        host.SetSession("Manager", "second.manager");
        var invalidSecondResponse = await host.Client.PostAsJsonAsync(
            $"/api/approvals/{host.Invoice.Id}/approve",
            new { username = "forged.director", role = "Director" });

        Assert.Equal(HttpStatusCode.Conflict, invalidSecondResponse.StatusCode);
        Assert.Contains(
            "Director",
            (await invalidSecondResponse.Content.ReadFromJsonAsync<JsonElement>())
                .GetProperty("error")
                .GetString());
        AssertInvoiceUnchanged(stateAfterFirstApproval, host.GetInvoice());

        host.SetSession("Director", "director.user");
        var secondResponse = await host.Client.PostAsJsonAsync(
            $"/api/approvals/{host.Invoice.Id}/approve",
            new { username = "forged.manager", role = "Manager" });

        Assert.Equal(HttpStatusCode.OK, secondResponse.StatusCode);
        var approvedInvoice = await secondResponse.Content.ReadFromJsonAsync<Invoice>();
        Assert.NotNull(approvedInvoice);
        Assert.Equal(InvoiceStatus.Approved, approvedInvoice.Status);
        Assert.Equal("director.user", approvedInvoice.DecidedBy);
        Assert.NotNull(approvedInvoice.DecidedAt);
        Assert.Collection(
            approvedInvoice.ApprovalHistory,
            first => Assert.Equal(("manager.user", "Manager"), (first.Approver, first.Role)),
            second => Assert.Equal(("director.user", "Director"), (second.Approver, second.Role)));
    }

    private static void AssertForbiddenAndUnchanged(
        HttpResponseMessage response,
        ApiTestHost host)
    {
        Assert.Equal(HttpStatusCode.Forbidden, response.StatusCode);
        AssertInvoiceUnchanged(host);
        response.Dispose();
    }

    private static void AssertUnauthorizedAndUnchanged(
        HttpResponseMessage response,
        ApiTestHost host)
    {
        Assert.Equal(HttpStatusCode.Unauthorized, response.StatusCode);
        AssertInvoiceUnchanged(host);
        response.Dispose();
    }

    private static Invoice SnapshotInvoice(Invoice invoice) =>
        new()
        {
            Id = invoice.Id,
            CustomerName = invoice.CustomerName,
            Amount = invoice.Amount,
            Status = invoice.Status,
            CreatedAt = invoice.CreatedAt,
            DecidedBy = invoice.DecidedBy,
            DecidedAt = invoice.DecidedAt,
            DecisionNote = invoice.DecisionNote,
            ApprovalHistory = invoice.ApprovalHistory.ToList(),
        };

    private static void AssertInvoiceUnchanged(ApiTestHost host) =>
        AssertInvoiceUnchanged(host.InitialInvoiceSnapshot, host.GetInvoice());

    private static void AssertInvoiceUnchanged(Invoice expected, Invoice actual)
    {
        Assert.Equal(expected.Id, actual.Id);
        Assert.Equal(expected.CustomerName, actual.CustomerName);
        Assert.Equal(expected.Amount, actual.Amount);
        Assert.Equal(expected.Status, actual.Status);
        Assert.Equal(expected.CreatedAt, actual.CreatedAt);
        Assert.Equal(expected.DecidedBy, actual.DecidedBy);
        Assert.Equal(expected.DecidedAt, actual.DecidedAt);
        Assert.Equal(expected.DecisionNote, actual.DecisionNote);
        Assert.Equal(expected.ApprovalHistory, actual.ApprovalHistory);
    }

    private sealed class ApiTestHost : IDisposable
    {
        private readonly TestServer _server;
        private readonly SessionStore _sessions;

        public ApiTestHost(string? role = null, string? username = null, decimal amount = 100m)
        {
            Invoices = new InMemoryInvoiceRepository();
            Invoice = Invoices.Add(new Invoice
            {
                Id = "INV-AUTH-1",
                CustomerName = "Authorization test invoice",
                Amount = amount,
                Status = InvoiceStatus.PendingApproval,
            });
            InitialInvoiceSnapshot = SnapshotInvoice(Invoice);

            _sessions = new SessionStore();
            var builder = new WebHostBuilder()
                .ConfigureServices(services =>
                {
                    services
                        .AddControllers()
                        .AddApplicationPart(typeof(ApprovalsController).Assembly);
                    services.AddSingleton(_sessions);
                    services.AddSingleton<IInvoiceRepository>(Invoices);
                    services.AddScoped<ApprovalService>();
                })
                .Configure(app =>
                {
                    app.UseRouting();
                    app.UseMiddleware<SessionAuthMiddleware>();
                    app.UseEndpoints(endpoints => endpoints.MapControllers());
                });

            _server = new TestServer(builder);
            Client = _server.CreateClient();

            if (role is not null && username is not null)
            {
                SetSession(role, username);
            }
        }

        public HttpClient Client { get; }
        public InMemoryInvoiceRepository Invoices { get; }
        public Invoice Invoice { get; }
        public Invoice InitialInvoiceSnapshot { get; }

        public Invoice GetInvoice() =>
            Invoices.GetById(Invoice.Id)
            ?? throw new InvalidOperationException($"Test invoice {Invoice.Id} disappeared.");

        public void SetSession(string role, string username)
        {
            var token = _sessions.Create(new UserSession(username, role));
            Client.DefaultRequestHeaders.Authorization =
                new AuthenticationHeaderValue("Bearer", token);
        }

        public void Dispose()
        {
            Client.Dispose();
            _server.Dispose();
        }
    }
}

using InvoiceApp.Api.Auth;
using InvoiceApp.Domain;
using Microsoft.AspNetCore.Mvc;

namespace InvoiceApp.Api.Controllers;

[ApiController]
[Route("api/[controller]")]
public class ApprovalsController : ApiControllerBase
{
    private readonly ApprovalService _approvals;

    public ApprovalsController(ApprovalService approvals)
    {
        _approvals = approvals;
    }

    public record RejectRequest(string Reason);

    [HttpPost("{invoiceId}/approve")]
    [RequireRole("Manager", "Director")]
    public ActionResult<Invoice> Approve(string invoiceId) =>
        Handle(() =>
        {
            var session = HttpContext.GetSession();
            return _approvals.Approve(invoiceId, session.Username, session.Role);
        });

    [HttpPost("{invoiceId}/reject")]
    [RequireRole("Approver", "Admin")]
    public ActionResult<Invoice> Reject(string invoiceId, [FromBody] RejectRequest request) =>
        Handle(() => _approvals.Reject(invoiceId, HttpContext.GetSession().Username, request.Reason));
}

using InvoiceApp.Domain;

namespace InvoiceApp.Api;

/// <summary>In-memory store so the demo app runs with no database. Seeded with a few invoices.</summary>
public class InMemoryInvoiceRepository : IInvoiceRepository
{
    private readonly object _lock = new();
    private int _nextNumber = 1006;

    private readonly List<Invoice> _invoices = new()
    {
        new Invoice { Id = "INV-1001", CustomerName = "Lakeside School District", Amount = 4250.00m, Status = InvoiceStatus.PendingApproval },
        new Invoice { Id = "INV-1002", CustomerName = "Hilltop Academy", Amount = 980.50m, Status = InvoiceStatus.PendingApproval },
        new Invoice { Id = "INV-1003", CustomerName = "Riverside Charter", Amount = 12300.00m, Status = InvoiceStatus.Approved, DecidedBy = "demo.approver", DecidedAt = DateTime.UtcNow.AddDays(-2) },
        new Invoice { Id = "INV-1004", CustomerName = "Oakwood Independent", Amount = 615.75m, Status = InvoiceStatus.PendingApproval },
        new Invoice { Id = "INV-1005", CustomerName = "Maple Grove Prep", Amount = 310.00m, Status = InvoiceStatus.Draft },
    };

    public IReadOnlyList<Invoice> GetAll()
    {
        lock (_lock) return _invoices.ToList();
    }

    public Invoice? GetById(string id)
    {
        lock (_lock) return _invoices.FirstOrDefault(i => i.Id == id);
    }

    public IReadOnlyList<Invoice> GetByIds(IEnumerable<string> ids)
    {
        var wanted = ids.ToHashSet();
        lock (_lock) return _invoices.Where(i => wanted.Contains(i.Id)).ToList();
    }

    public Invoice Add(Invoice invoice)
    {
        lock (_lock)
        {
            if (string.IsNullOrEmpty(invoice.Id))
            {
                invoice.Id = $"INV-{_nextNumber++}";
            }

            _invoices.Add(invoice);
            return invoice;
        }
    }

    public void Update(Invoice invoice)
    {
        lock (_lock)
        {
            var index = _invoices.FindIndex(i => i.Id == invoice.Id);
            if (index >= 0) _invoices[index] = invoice;
        }
    }

    public T ExecuteAtomically<T>(string id, Func<Invoice?, T> operation)
    {
        lock (_lock)
        {
            return operation(_invoices.FirstOrDefault(invoice => invoice.Id == id));
        }
    }

    public bool Remove(string id)
    {
        lock (_lock) return _invoices.RemoveAll(i => i.Id == id) > 0;
    }
}

import { expect, test } from '@playwright/test';
import { InvoiceApprovalPage } from '../pages/invoice-approval-page';

test('high-value invoice stays pending until a distinct Director approves', async ({ page }) => {
  const invoicePage = new InvoiceApprovalPage(page);
  const customerName = `Two approver check ${Date.now()}`;

  await invoicePage.open();
  await invoicePage.signIn('demo.manager', 'ChangeMe123!', 'Manager');
  const invoiceId = await invoicePage.createAndSubmitInvoice(customerName, 500_001);

  await invoicePage.approve(invoiceId);
  await invoicePage.expectProvisionalApproval(invoiceId, 'demo.manager', 'Manager');
  const provisionalInvoice = await invoicePage.getAuthenticatedInvoice(invoiceId);
  expect(provisionalInvoice.status).toBe('PendingApproval');
  expect(provisionalInvoice.decidedBy).toBeNull();
  expect(provisionalInvoice.decidedAt).toBeNull();
  expect(provisionalInvoice.approvalHistory).toHaveLength(1);
  expect(provisionalInvoice.approvalHistory[0]).toMatchObject({
    approver: 'demo.manager',
    role: 'Manager',
  });
  expect(provisionalInvoice.approvalHistory[0].approvedAt).toBeTruthy();

  await invoicePage.signOut();
  await invoicePage.signIn('demo.director', 'ChangeMe123!', 'Director');
  await invoicePage.approve(invoiceId);
  await invoicePage.expectApproved(invoiceId, customerName);

  const approvedInvoice = await invoicePage.getAuthenticatedInvoice(invoiceId);
  expect(approvedInvoice.status).toBe('Approved');
  expect(approvedInvoice.decidedBy).toBe('demo.director');
  expect(approvedInvoice.decidedAt).toBeTruthy();
  expect(approvedInvoice.approvalHistory).toHaveLength(2);
  expect(approvedInvoice.approvalHistory.map((record: { approver: string }) => record.approver))
    .toEqual(['demo.manager', 'demo.director']);
});

import { expect, test } from '@playwright/test';
import { InvoiceApprovalPage } from '../pages/invoice-approval-page';

test('Manager cannot approve an invoice above 50000 through the UI', async ({ page }) => {
  const invoicePage = new InvoiceApprovalPage(page);
  const customerName = `Manager limit check ${Date.now()}`;

  await invoicePage.open();
  await invoicePage.signIn('demo.manager', 'ChangeMe123!');
  const invoiceId = await invoicePage.createAndSubmitInvoice(customerName, 50_001);

  await invoicePage.approveAsManager(invoiceId);

  await invoicePage.expectDecisionError('Managers may approve invoices only up to 50000.');
  await invoicePage.expectPendingApproval(invoiceId, customerName);

  const invoice = await invoicePage.getAuthenticatedInvoice(invoiceId);
  expect(invoice.status).toBe('PendingApproval');
  expect(invoice.decidedBy).toBeNull();
  expect(invoice.decidedAt).toBeNull();
});

import { expect, Page } from '@playwright/test';

export class InvoiceApprovalPage {
  constructor(private readonly page: Page) {}

  async open() {
    await this.page.goto('/');
  }

  async signIn(username: string, password: string, role = 'Manager') {
    await this.page.getByLabel('Username').fill(username);
    await this.page.getByLabel('Password').fill(password);
    await this.page.getByRole('button', { name: 'Sign in' }).click();
    await expect(this.page.getByText(`${username} (${role})`, { exact: true })).toBeVisible();
  }

  async createAndSubmitInvoice(customerName: string, amount: number) {
    await this.page.getByLabel('Customer name').fill(customerName);
    await this.page.getByLabel('Amount').fill(String(amount));
    await this.page.getByRole('button', { name: 'Create invoice' }).click();

    const invoiceRow = this.page
      .getByRole('row')
      .filter({ hasText: customerName });
    await expect(invoiceRow).toBeVisible();
    await invoiceRow
      .getByRole('button', { name: /Submit invoice .* for approval/ })
      .click();
    await expect(invoiceRow.getByRole('cell').nth(3)).toHaveText('Pending Approval');
    return invoiceRow.getByRole('cell').nth(0).innerText();
  }

  async approveAsManager(invoiceId: string) {
    await this.approve(invoiceId);
  }

  async approve(invoiceId: string) {
    await this.page.getByRole('tab', { name: 'Approvals' }).click();
    await this.page
      .getByRole('button', { name: `Approve invoice ${invoiceId}` })
      .click();
  }

  async signOut() {
    await this.page.getByRole('button', { name: 'Sign out' }).click();
    await expect(this.page.getByRole('button', { name: 'Sign in' })).toBeVisible();
  }

  async expectProvisionalApproval(invoiceId: string, approver: string, role: string) {
    await expect(
      this.page.getByRole('status').filter({
        hasText: `Provisional approval recorded by ${approver} (${role}). Awaiting a different Director.`,
      })
    ).toBeVisible();
    await expect(
      this.page.getByRole('listitem').filter({ hasText: invoiceId })
    ).toBeVisible();
  }

  async expectPendingApproval(invoiceId: string, customerName: string) {
    await this.page.getByRole('tab', { name: 'Invoices' }).click();
    const invoiceRow = this.page
      .getByRole('row')
      .filter({ hasText: customerName });
    await expect(invoiceRow.getByRole('cell').nth(3)).toHaveText('Pending Approval');

    await this.page.getByRole('tab', { name: 'Approvals' }).click();
    const pendingInvoice = this.page
      .getByRole('listitem')
      .filter({ hasText: invoiceId });
    await expect(pendingInvoice).toBeVisible();
  }

  async expectApproved(invoiceId: string, customerName: string) {
    await this.page.getByRole('tab', { name: 'Invoices' }).click();
    const invoiceRow = this.page
      .getByRole('row')
      .filter({ hasText: customerName });
    await expect(invoiceRow.getByRole('cell').nth(3)).toHaveText('Approved');
    await expect(invoiceRow).toContainText(invoiceId);
  }

  async getAuthenticatedInvoice(invoiceId: string) {
    const token = await this.page.evaluate(() => {
      const session = JSON.parse(sessionStorage.getItem('session') ?? 'null');
      return session?.token;
    });

    const response = await this.page.request.get(`/api/invoices/${invoiceId}`, {
      headers: { Authorization: `Bearer ${token}` },
    });
    expect(response.ok()).toBeTruthy();
    return response.json();
  }

  async expectDecisionError(message: string) {
    await expect(this.page.getByRole('alert').filter({ hasText: message })).toBeVisible();
  }
}

