import { expect, test } from '@playwright/test';
import { InvoiceApprovalPage } from '../pages/invoice-approval-page';

test('high-value invoice stays pending until a distinct Director approves', async ({ page }) => {
  const invoicePage = new InvoiceApprovalPage(page);
  const customerName = `Two approver check ${Date.now()}`;

  await invoicePage.open();
  await invoicePage.signIn('demo.manager', 'ChangeMe123!', 'Manager');
  const invoiceId = await invoicePage.createAndSubmitInvoice(customerName, 500_001);

  await invoicePage.approve(invoiceId);
  await invoicePage.expectProvisionalApproval(invoiceId, 'demo.manager', 'Manager');
  const provisionalInvoice = await invoicePage.getAuthenticatedInvoice(invoiceId);
  expect(provisionalInvoice.status).toBe('PendingApproval');
  expect(provisionalInvoice.decidedBy).toBeNull();
  expect(provisionalInvoice.decidedAt).toBeNull();
  expect(provisionalInvoice.approvalHistory).toHaveLength(1);
  expect(provisionalInvoice.approvalHistory[0]).toMatchObject({
    approver: 'demo.manager',
    role: 'Manager',
  });
  expect(provisionalInvoice.approvalHistory[0].approvedAt).toBeTruthy();

  await invoicePage.signOut();
  await invoicePage.signIn('demo.director', 'ChangeMe123!', 'Director');
  await invoicePage.approve(invoiceId);
  await invoicePage.expectApproved(invoiceId, customerName);

  const approvedInvoice = await invoicePage.getAuthenticatedInvoice(invoiceId);
  expect(approvedInvoice.status).toBe('Approved');
  expect(approvedInvoice.decidedBy).toBe('demo.director');
  expect(approvedInvoice.decidedAt).toBeTruthy();
  expect(approvedInvoice.approvalHistory).toHaveLength(2);
  expect(approvedInvoice.approvalHistory.map((record: { approver: string }) => record.approver))
    .toEqual(['demo.manager', 'demo.director']);
});

import { expect, Page } from '@playwright/test';

export class InvoiceApprovalPage {
  constructor(private readonly page: Page) {}

  async open() {
    await this.page.goto('/');
  }

  async signIn(username: string, password: string, role = 'Manager') {
    await this.page.getByLabel('Username').fill(username);
    await this.page.getByLabel('Password').fill(password);
    await this.page.getByRole('button', { name: 'Sign in' }).click();
    await expect(this.page.getByText(`${username} (${role})`, { exact: true })).toBeVisible();
  }

  async createAndSubmitInvoice(customerName: string, amount: number) {
    await this.page.getByLabel('Customer name').fill(customerName);
    await this.page.getByLabel('Amount').fill(String(amount));
    await this.page.getByRole('button', { name: 'Create invoice' }).click();

    const invoiceRow = this.page
      .getByRole('row')
      .filter({ hasText: customerName });
    await expect(invoiceRow).toBeVisible();
    await invoiceRow
      .getByRole('button', { name: /Submit invoice .* for approval/ })
      .click();
    await expect(invoiceRow.getByRole('cell').nth(3)).toHaveText('Pending Approval');
    return invoiceRow.getByRole('cell').nth(0).innerText();
  }

  async approveAsManager(invoiceId: string) {
    await this.approve(invoiceId);
  }

  async approve(invoiceId: string) {
    await this.page.getByRole('tab', { name: 'Approvals' }).click();
    await this.page
      .getByRole('button', { name: `Approve invoice ${invoiceId}` })
      .click();
  }

  async signOut() {
    await this.page.getByRole('button', { name: 'Sign out' }).click();
    await expect(this.page.getByRole('button', { name: 'Sign in' })).toBeVisible();
  }

  async expectProvisionalApproval(invoiceId: string, approver: string, role: string) {
    await expect(
      this.page.getByRole('status').filter({
        hasText: `Provisional approval recorded by ${approver} (${role}). Awaiting a different Director.`,
      })
    ).toBeVisible();
    await expect(
      this.page.getByRole('listitem').filter({ hasText: invoiceId })
    ).toBeVisible();
  }

  async expectPendingApproval(invoiceId: string, customerName: string) {
    await this.page.getByRole('tab', { name: 'Invoices' }).click();
    const invoiceRow = this.page
      .getByRole('row')
      .filter({ hasText: customerName });
    await expect(invoiceRow.getByRole('cell').nth(3)).toHaveText('Pending Approval');

    await this.page.getByRole('tab', { name: 'Approvals' }).click();
    const pendingInvoice = this.page
      .getByRole('listitem')
      .filter({ hasText: invoiceId });
    await expect(pendingInvoice).toBeVisible();
  }

  async expectApproved(invoiceId: string, customerName: string) {
    await this.page.getByRole('tab', { name: 'Invoices' }).click();
    const invoiceRow = this.page
      .getByRole('row')
      .filter({ hasText: customerName });
    await expect(invoiceRow.getByRole('cell').nth(3)).toHaveText('Approved');
    await expect(invoiceRow).toContainText(invoiceId);
  }

  async getAuthenticatedInvoice(invoiceId: string) {
    const token = await this.page.evaluate(() => {
      const session = JSON.parse(sessionStorage.getItem('session') ?? 'null');
      return session?.token;
    });

    const response = await this.page.request.get(`/api/invoices/${invoiceId}`, {
      headers: { Authorization: `Bearer ${token}` },
    });
    expect(response.ok()).toBeTruthy();
    return response.json();
  }

  async expectDecisionError(message: string) {
    await expect(this.page.getByRole('alert').filter({ hasText: message })).toBeVisible();
  }
}

