  13:     }
  14: 
  15:     public Invoice Submit(string invoiceId)
  16:     {
  17:         return _repository.ExecuteAtomically(invoiceId, currentInvoice =>
  18:         {
  19:             var invoice = Find(currentInvoice, invoiceId);
  20: 
  21:             if (invoice.Status != InvoiceStatus.Draft)
  22:             {
  23:                 throw new InvalidOperationException(
  24:                     $"Invoice {invoiceId} is {invoice.Status}; only drafts can be submitted.");
  25:             }
  26: 
  27:             invoice.Status = InvoiceStatus.PendingApproval;
  28:             _repository.Update(invoice);
  29:             return invoice;
  30:         });
  31:     }
  32: 
  33:     public Invoice Approve(string invoiceId, string approver, string role)
  34:     {
  35:         return _repository.ExecuteAtomically(invoiceId, currentInvoice =>
  36:         {
  37:             var invoice = Find(currentInvoice, invoiceId);
  38:             EnsurePending(invoice);
  39: 
  40:             if (invoice.Amount > 500_000m)
  41:             {
  42:                 return ApproveHighValueInvoice(invoice, approver, role);
  43:             }
  44: 
  45:             EnsureApprovalAllowed(invoice, role);
  46:             EnsureNoExistingApprovalHistory(invoice);
  47: 
  48:             var approvedAt = DateTime.UtcNow;
  49:             invoice.ApprovalHistory.Add(new ApprovalRecord(approver, role, approvedAt));
  50:             FinalizeApproval(invoice, approver, approvedAt);
  51:             _repository.Update(invoice);
  52:             return invoice;
  53:         });
  54:     }
  55: 
  56:     public Invoice Reject(string invoiceId, string approver, string reason)
  57:     {
  58:         if (string.IsNullOrWhiteSpace(reason))
  59:         {
  60:             throw new ArgumentException("A reason is required to reject an invoice.", nameof(reason));
  61:         }
  62: 
  63:         return _repository.ExecuteAtomically(invoiceId, currentInvoice =>
  64:         {
  65:             var invoice = Find(currentInvoice, invoiceId);
  66:             EnsurePending(invoice);
  67: 
  68:             invoice.Status = InvoiceStatus.Rejected;
  69:             invoice.DecidedBy = approver;
  70:             invoice.DecidedAt = DateTime.UtcNow;
  71:             invoice.DecisionNote = reason;
  72:             _repository.Update(invoice);
  73:             return invoice;
  74:         });
  75:     }
  76: 
  77:     private static Invoice Find(Invoice? invoice, string invoiceId) =>
  78:         invoice
  79:         ?? throw new KeyNotFoundException($"Invoice {invoiceId} was not found.");
  80: 
  81:     private static void EnsurePending(Invoice invoice)
  82:     {
  83:         if (invoice.Status != InvoiceStatus.PendingApproval)
  84:         {
  85:             throw new InvalidOperationException(
  86:                 $"Invoice {invoice.Id} is {invoice.Status}; only pending invoices can be decided.");
  87:         }
  88:     }
  89: 
  90:     private static void EnsureApprovalAllowed(Invoice invoice, string role)
  91:     {
  92:         if (role == "Manager" && invoice.Amount <= 50_000m)
  93:         {
  94:             return;
  95:         }
  96: 
  97:         if (role == "Director" && invoice.Amount <= 500_000m)
  98:         {
  99:             return;
 100:         }
 101: 
 102:         var reason = role switch
 103:         {
 104:             "Manager" => "Managers may approve invoices only up to 50000.",
 105:             "Director" => "Directors may approve invoices only up to 500000 in a single approval.",
 106:             _ => $"Role '{role}' is not authorized to approve invoices.",
 107:         };
 108: 
 109:         throw new InvalidOperationException(reason);
 110:     }
 111: 
 112:     private Invoice ApproveHighValueInvoice(Invoice invoice, string approver, string role)
 113:     {
 114:         if (invoice.ApprovalHistory.Count == 0)
 115:         {
 116:             if (role is not ("Manager" or "Director"))
 117:             {
 118:                 throw new InvalidOperationException(
 119:                     $"Role '{role}' is not authorized to provide a provisional approval.");
 120:             }
 121: 
 122:             invoice.ApprovalHistory.Add(
 123:                 new ApprovalRecord(approver, role, DateTime.UtcNow));
 124:             _repository.Update(invoice);
 125:             return invoice;
 126:         }
 127: 
 128:         if (invoice.ApprovalHistory.Count != 1)
 129:         {
 130:             throw new InvalidOperationException(
 131:                 "The pending invoice has an invalid approval history.");
 132:         }
 133: 
 134:         var firstApproval = invoice.ApprovalHistory[0];
 135:         if (string.Equals(firstApproval.Approver, approver, StringComparison.OrdinalIgnoreCase))
 136:         {
 137:             throw new InvalidOperationException(
 138:                 "The second approval must be made by a different user.");
 139:         }
 140: 
 141:         if (role != "Director")
 142:         {
 143:             throw new InvalidOperationException(
 144:                 "The second approver for invoices above 500000 must be a Director.");
 145:         }
 146: 
 147:         var approvedAt = DateTime.UtcNow;
 148:         invoice.ApprovalHistory.Add(new ApprovalRecord(approver, role, approvedAt));
 149:         FinalizeApproval(invoice, approver, approvedAt);
 150:         _repository.Update(invoice);
 151:         return invoice;
 152:     }
 153: 
 154:     private static void EnsureNoExistingApprovalHistory(Invoice invoice)
 155:     {
 156:         if (invoice.ApprovalHistory.Count != 0)
 157:         {
 158:             throw new InvalidOperationException(
 159:                 "A single-approval invoice cannot already have approval history.");
 160:         }
 161:     }
 162: 
 163:     private static void FinalizeApproval(Invoice invoice, string approver, DateTime approvedAt)
 164:     {
 165:         invoice.Status = InvoiceStatus.Approved;
 166:         invoice.DecidedBy = approver;
 167:         invoice.DecidedAt = approvedAt;
 168:     }
