namespace InvoiceApp.Domain;

/// <summary>
/// Moves invoices through submission, approval, and rejection.
/// </summary>
public class ApprovalService
{
    private readonly IInvoiceRepository _repository;

    public ApprovalService(IInvoiceRepository repository)
    {
        _repository = repository;
    }

    public Invoice Submit(string invoiceId)
    {
        return _repository.ExecuteAtomically(invoiceId, currentInvoice =>
        {
            var invoice = Find(currentInvoice, invoiceId);

            if (invoice.Status != InvoiceStatus.Draft)
            {
                throw new InvalidOperationException(
                    $"Invoice {invoiceId} is {invoice.Status}; only drafts can be submitted.");
            }

            invoice.Status = InvoiceStatus.PendingApproval;
            _repository.Update(invoice);
            return invoice;
        });
    }

    public Invoice Approve(string invoiceId, string approver, string role)
    {
        return _repository.ExecuteAtomically(invoiceId, currentInvoice =>
        {
            var invoice = Find(currentInvoice, invoiceId);
            EnsurePending(invoice);

            if (invoice.Amount > 500_000m)
            {
                return ApproveHighValueInvoice(invoice, approver, role);
            }

            EnsureApprovalAllowed(invoice, role);
            EnsureNoExistingApprovalHistory(invoice);

            var approvedAt = DateTime.UtcNow;
            invoice.ApprovalHistory.Add(new ApprovalRecord(approver, role, approvedAt));
            FinalizeApproval(invoice, approver, approvedAt);
            _repository.Update(invoice);
            return invoice;
        });
    }

    public Invoice Reject(string invoiceId, string approver, string reason)
    {
        if (string.IsNullOrWhiteSpace(reason))
        {
            throw new ArgumentException("A reason is required to reject an invoice.", nameof(reason));
        }

        return _repository.ExecuteAtomically(invoiceId, currentInvoice =>
        {
            var invoice = Find(currentInvoice, invoiceId);
            EnsurePending(invoice);

            invoice.Status = InvoiceStatus.Rejected;
            invoice.DecidedBy = approver;
            invoice.DecidedAt = DateTime.UtcNow;
            invoice.DecisionNote = reason;
            _repository.Update(invoice);
            return invoice;
        });
    }

    private static Invoice Find(Invoice? invoice, string invoiceId) =>
        invoice
        ?? throw new KeyNotFoundException($"Invoice {invoiceId} was not found.");

    private static void EnsurePending(Invoice invoice)
    {
        if (invoice.Status != InvoiceStatus.PendingApproval)
        {
            throw new InvalidOperationException(
                $"Invoice {invoice.Id} is {invoice.Status}; only pending invoices can be decided.");
        }
    }

    private static void EnsureApprovalAllowed(Invoice invoice, string role)
    {
        if (role == "Manager" && invoice.Amount <= 50_000m)
        {
            return;
        }

        if (role == "Director" && invoice.Amount <= 500_000m)
        {
            return;
        }

        var reason = role switch
        {
            "Manager" => "Managers may approve invoices only up to 50000.",
            "Director" => "Directors may approve invoices only up to 500000 in a single approval.",
            _ => $"Role '{role}' is not authorized to approve invoices.",
        };

        throw new InvalidOperationException(reason);
    }

    private Invoice ApproveHighValueInvoice(Invoice invoice, string approver, string role)
    {
        if (invoice.ApprovalHistory.Count == 0)
        {
            if (role is not ("Manager" or "Director"))
            {
                throw new InvalidOperationException(
                    $"Role '{role}' is not authorized to provide a provisional approval.");
            }

            invoice.ApprovalHistory.Add(
                new ApprovalRecord(approver, role, DateTime.UtcNow));
            _repository.Update(invoice);
            return invoice;
        }

        if (invoice.ApprovalHistory.Count != 1)
        {
            throw new InvalidOperationException(
                "The pending invoice has an invalid approval history.");
        }

        var firstApproval = invoice.ApprovalHistory[0];
        if (string.Equals(firstApproval.Approver, approver, StringComparison.OrdinalIgnoreCase))
        {
            throw new InvalidOperationException(
                "The second approval must be made by a different user.");
        }

        if (role != "Director")
        {
            throw new InvalidOperationException(
                "The second approver for invoices above 500000 must be a Director.");
        }

        var approvedAt = DateTime.UtcNow;
        invoice.ApprovalHistory.Add(new ApprovalRecord(approver, role, approvedAt));
        FinalizeApproval(invoice, approver, approvedAt);
        _repository.Update(invoice);
        return invoice;
    }

    private static void EnsureNoExistingApprovalHistory(Invoice invoice)
    {
        if (invoice.ApprovalHistory.Count != 0)
        {
            throw new InvalidOperationException(
                "A single-approval invoice cannot already have approval history.");
        }
    }

    private static void FinalizeApproval(Invoice invoice, string approver, DateTime approvedAt)
    {
        invoice.Status = InvoiceStatus.Approved;
        invoice.DecidedBy = approver;
        invoice.DecidedAt = approvedAt;
    }
}

import { expect, test } from '@playwright/test';
import { InvoiceApprovalPage } from '../pages/invoice-approval-page';

test('high-value invoice stays pending until a distinct Director approves', async ({ page }) => {
  const invoicePage = new InvoiceApprovalPage(page);
  const customerName = `Two approver check ${Date.now()}`;

  await invoicePage.open();
  await invoicePage.signIn('demo.manager', 'ChangeMe123!', 'Manager');
  const invoiceId = await invoicePage.createAndSubmitInvoice(customerName, 500_001);

  await invoicePage.approve(invoiceId);
  await invoicePage.expectProvisionalApproval(invoiceId, 'demo.manager', 'Manager');
  const provisionalInvoice = await invoicePage.getAuthenticatedInvoice(invoiceId);
  expect(provisionalInvoice.status).toBe('PendingApproval');
  expect(provisionalInvoice.decidedBy).toBeNull();
  expect(provisionalInvoice.decidedAt).toBeNull();
  expect(provisionalInvoice.approvalHistory).toHaveLength(1);
  expect(provisionalInvoice.approvalHistory[0]).toMatchObject({
    approver: 'demo.manager',
    role: 'Manager',
  });
  expect(provisionalInvoice.approvalHistory[0].approvedAt).toBeTruthy();

  await invoicePage.signOut();
  await invoicePage.signIn('demo.director', 'ChangeMe123!', 'Director');
  await invoicePage.approve(invoiceId);
  await invoicePage.expectApproved(invoiceId, customerName);

  const approvedInvoice = await invoicePage.getAuthenticatedInvoice(invoiceId);
  expect(approvedInvoice.status).toBe('Approved');
  expect(approvedInvoice.decidedBy).toBe('demo.director');
  expect(approvedInvoice.decidedAt).toBeTruthy();
  expect(approvedInvoice.approvalHistory).toHaveLength(2);
  expect(approvedInvoice.approvalHistory.map((record: { approver: string }) => record.approver))
    .toEqual(['demo.manager', 'demo.director']);
});

using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.Filters;

namespace InvoiceApp.Api.Auth;

/// <summary>Allows the action only for the listed roles; everyone else gets 403.</summary>
[AttributeUsage(AttributeTargets.Class | AttributeTargets.Method)]
public class RequireRoleAttribute : ActionFilterAttribute
{
    private readonly string[] _roles;

    public RequireRoleAttribute(params string[] roles)
    {
        _roles = roles;
    }

    public string? ForbiddenMessage { get; set; }

    public override void OnActionExecuting(ActionExecutingContext context)
    {
        var session = context.HttpContext.Items[HttpContextExtensions.SessionKey] as UserSession;

        if (session is null || !_roles.Contains(session.Role))
        {
            context.Result = ForbiddenMessage is null
                ? new StatusCodeResult(StatusCodes.Status403Forbidden)
                : new ObjectResult(new { error = ForbiddenMessage })
                {
                    StatusCode = StatusCodes.Status403Forbidden,
                };
        }
    }
}

using InvoiceApp.Api.Auth;
using InvoiceApp.Domain;
using Microsoft.AspNetCore.Mvc;

namespace InvoiceApp.Api.Controllers;

[ApiController]
[Route("api/[controller]")]
public class ApprovalsController : ApiControllerBase
{
    private readonly ApprovalService _approvals;

    public ApprovalsController(ApprovalService approvals)
    {
        _approvals = approvals;
    }

    public record RejectRequest(string Reason);

    [HttpPost("{invoiceId}/approve")]
    [RequireRole(
        "Manager",
        "Director",
        ForbiddenMessage = "A Manager or Director role is required to approve the invoice.")]
    public ActionResult<Invoice> Approve(string invoiceId) =>
        Handle(() =>
        {
            var session = HttpContext.GetSession();
            return _approvals.Approve(invoiceId, session.Username, session.Role);
        });

    [HttpPost("{invoiceId}/reject")]
    [RequireRole("Approver", "Admin")]
    public ActionResult<Invoice> Reject(string invoiceId, [FromBody] RejectRequest request) =>
        Handle(() => _approvals.Reject(invoiceId, HttpContext.GetSession().Username, request.Reason));
}

using InvoiceApp.Domain;

namespace InvoiceApp.Api;

/// <summary>In-memory store so the demo app runs with no database. Seeded with a few invoices.</summary>
public class InMemoryInvoiceRepository : IInvoiceRepository
{
    private readonly object _lock = new();
    private int _nextNumber = 1006;

    private readonly List<Invoice> _invoices = new()
    {
        new Invoice { Id = "INV-1001", CustomerName = "Lakeside School District", Amount = 4250.00m, Status = InvoiceStatus.PendingApproval },
        new Invoice { Id = "INV-1002", CustomerName = "Hilltop Academy", Amount = 980.50m, Status = InvoiceStatus.PendingApproval },
        new Invoice { Id = "INV-1003", CustomerName = "Riverside Charter", Amount = 12300.00m, Status = InvoiceStatus.Approved, DecidedBy = "demo.approver", DecidedAt = DateTime.UtcNow.AddDays(-2) },
        new Invoice { Id = "INV-1004", CustomerName = "Oakwood Independent", Amount = 615.75m, Status = InvoiceStatus.PendingApproval },
        new Invoice { Id = "INV-1005", CustomerName = "Maple Grove Prep", Amount = 310.00m, Status = InvoiceStatus.Draft },
    };

    public IReadOnlyList<Invoice> GetAll()
    {
        lock (_lock) return _invoices.ToList();
    }

    public Invoice? GetById(string id)
    {
        lock (_lock) return _invoices.FirstOrDefault(i => i.Id == id);
    }

    public IReadOnlyList<Invoice> GetByIds(IEnumerable<string> ids)
    {
        var wanted = ids.ToHashSet();
        lock (_lock) return _invoices.Where(i => wanted.Contains(i.Id)).ToList();
    }

    public Invoice Add(Invoice invoice)
    {
        lock (_lock)
        {
            if (string.IsNullOrEmpty(invoice.Id))
            {
                invoice.Id = $"INV-{_nextNumber++}";
            }

            _invoices.Add(invoice);
            return invoice;
        }
    }

    public void Update(Invoice invoice)
    {
        lock (_lock)
        {
            var index = _invoices.FindIndex(i => i.Id == invoice.Id);
            if (index >= 0) _invoices[index] = invoice;
        }
    }

    public T ExecuteAtomically<T>(string id, Func<Invoice?, T> operation)
    {
        lock (_lock)
        {
            return operation(_invoices.FirstOrDefault(invoice => invoice.Id == id));
        }
    }

    public bool Remove(string id)
    {
        lock (_lock) return _invoices.RemoveAll(i => i.Id == id) > 0;
    }
}

using InvoiceApp.Api;
