    }

    [Fact]
    public async Task Approve_MissingBearerToken_UnauthorizedWithoutMutation()
    {
        using var host = new ApiTestHost();

        var response = await host.Client.PostAsync(
            $"/api/approvals/{host.Invoice.Id}/approve",
